timeseries r = sum(log.nexus.adapter.responses), by: { nexus.cluster, nexus.outcome }
| fieldsAdd n = arraySum(r)
| summarize total = sum(n), errors = sum(if(nexus.outcome == "error", n, else: 0)),
    business_412 = sum(if(nexus.outcome == "business_412", n, else: 0)), by: { nexus.cluster }
| fieldsAdd pct_error = round(100.0 * errors / total, decimals: 2)
| sort pct_error desc

timeseries c = sum(log.nexus.adapter.backend_calls), by: { nexus.component, nexus.latency_bucket }
| fieldsAdd n = arraySum(c)
| summarize total = sum(n), slow = sum(if(in(nexus.latency_bucket, array("1-5s", "5s+")), n, else: 0)), by: { nexus.component }
| fieldsAdd pct_slow = round(100.0 * slow / total, decimals: 2)
| sort pct_slow desc

// C (corregido) is shown on its own until the business defines whether it counts as success or failure
timeseries s = sum(log.nexus.mngr.soap_responses), by: { nexus.cluster, nexus.acceptance }
| fieldsAdd n = arraySum(s)
| summarize total = sum(n), b = sum(if(nexus.acceptance == "B", n, else: 0)),
    m = sum(if(nexus.acceptance == "M", n, else: 0)), c = sum(if(nexus.acceptance == "C", n, else: 0)), by: { nexus.cluster }
| fieldsAdd pct_b = round(100.0 * b / total, decimals: 2), pct_m = round(100.0 * m / total, decimals: 2),
            pct_c = round(100.0 * c / total, decimals: 2)
| sort pct_m desc

timeseries s = sum(log.nexus.mngr.soap_responses), by: { nexus.cluster, nexus.soap.operation, nexus.acceptance }
| fieldsAdd n = arraySum(s)
| summarize total = sum(n), m = sum(if(nexus.acceptance == "M", n, else: 0)), by: { nexus.cluster, nexus.soap.operation }
| fieldsAdd pct_m = round(100.0 * m / total, decimals: 2)
| sort m desc
| limit 20

// late replies = Stratus answered after the adapter gave up; a 504 without a late reply = Stratus never answered
timeseries timeouts = sum(log.nexus.adapter.timeouts), late_replies = sum(log.nexus.adapter.stratus_late_replies),
    by: { nexus.cluster }, interval: 5m
